 {toast&&<div className="toast" role="status"><CheckCircle2 size={18}/>{toast}</div>}{busy&&<div className="loading-bar"/>}
 {modal==='project'&&<Modal title="مساحة جديدة لأفكار فريقك" onClose={()=>setModal('')}><form onSubmit={async e=>{e.preventDefault();const f=new FormData(e.currentTarget);const r=await mutate('createProject',{title:f.get('title'),description:f.get('description'),space:f.get('space')},true);if(r)open(r.id,'references')}}><p className="form-intro">ابدأ بالاسم والهدف. ثم أضف المرجعيات وقالب المخرج وادعُ الفريق.</p><label>اسم المشروع<input name="title" maxLength={150} required autoFocus placeholder="مثلًا: تصميم تجربة المستفيد"/></label><label>وصف مختصر<textarea name="description" maxLength={2000} rows={3} placeholder="ما الذي تريدون الوصول إليه معًا؟"/></label><label>مساحة العمل<select name="space" defaultValue={space==='all'?data?.spaces?.[0]?.id||'':space}>{data?.spaces?.length?data.spaces.map((s:any)=><option key={s.id} value={s.id}>{s.title}</option>):<option value="">مساحتي</option>}</select></label><div className="modal-footer"><button type="button" className="btn secondary" onClick={()=>setModal('')}>إلغاء</button><button disabled={busy} className="btn">إنشاء المشروع <ArrowUpLeft size={17}/></button></div></form></Modal>}
